        PasswordBox Secret(string original){string text=SettingsStore.ReadForSettings(original);if(original.Length>0&&text.Length==0)reset=true;return new(){Password=text,Padding=new(9),Margin=new(0,3,0,10)};}
        var key=Secret(config.LlmKeyProtected);var web=Secret(config.MapServiceKeyProtected);var js=Secret(config.MapJsKeyProtected);var security=Secret(config.MapSecurityProtected);var json=new CheckBox{Content="使用JSON响应模式",IsChecked=config.JsonMode};Ui.Field(ai,"需求识别服务",provider);Ui.Field(ai,"兼容接口地址（/v1 或完整 chat/completions）",endpoint);Ui.Field(ai,"模型名称",model);Ui.Field(ai,"模型API密钥",key);Ui.Field(ai,"百炼地域",region);Ui.Field(ai,"百炼业务空间API Host（可留空）",host);ai.Children.Add(json);
